# Verify candidate rule against all 4 demos: find singleton markers (not part of group), 
# draw full-length bar in marker's column/row in background color, set marker to 4.
from collections import Counter
def solve(inp):
    o=[r[:] for r in inp]
    h,w=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    # find singleton markers: cells whose color count ==1? demo3 ones at (6,3),(7,20) each singleton... but also many 3s. Use "isolated": cell with no same-color neighbor (4-neighborhood).
    singles=[]
    for i in range(h):
        for j in range(w):
            v=inp[i][j]; nb=[inp[i+di][j+dj] for di,dj in [(-1,0),(1,0),(0,-1),(0,1)] if 0<=i+di<h and 0<=j+dj<w and inp[i+di][j+dj]==v]
            if not nb: singles.append((i,j,v))
    cols={c for _,_,_ in singles}
    rows={r for _,_,_ in singles}
    for i,j,v in singles: o[i][j]=4
    for c in cols:
        for r in range(h):
            if o[r][c]==bg: o[r][c]=bg
    for r in rows:
        for c in range(w):
            if o[r][c]==bg: o[r][c]=bg
    return o
